import { useState, useCallback, useEffect, useRef, lazy, Suspense } from "react";
import type { FeedDensity } from "@/components/dashboard/feedDensity";

import { toast } from "sonner";
import { usePullToRefresh } from "@/hooks/usePullToRefresh";
import { useNavigate, useSearchParams } from "react-router-dom";
import { signOutWithPushCleanup } from "@/lib/authSignOut";
import { PageScaffold } from "@/components/ui/PageScaffold";
import { DashboardSkeleton } from "@/components/SkeletonLoaders";
import { LoadingHeading } from "@/components/ui/LoadingHeading";
import { useRealtimePush } from "@/hooks/useRealtimePush";
import { usePageTitle } from "@/hooks/usePageTitle";
import { isProfileComplete } from "@/components/ProtectedRoute";
// TITLE_BAR_PADDING ships WITH the bar it is sized for, so Home and the
// guest feed cannot drift apart on the one measurement that makes the row
// read as a band of chrome rather than a card.
import { DashboardTitleBar, TITLE_BAR_PADDING } from "@/components/dashboard/DashboardTitleBar";
import { BrowseSearchBar } from "@/components/dashboard/browseTasksToolbar/BrowseSearchBar";
import { BrowseTasksToolbar } from "@/components/dashboard/BrowseTasksToolbar";
import { BrowseTasksActions } from "@/components/dashboard/browseTasksToolbar/BrowseTasksActions";
import { BrowseTasksFeed } from "@/components/dashboard/BrowseTasksFeed";
import { PushNotificationPrompt } from "@/components/PushNotificationPrompt";
import { useIsWebDesktop } from "@/components/DesktopSidebarNav";
import { Map, MapPinned } from "lucide-react";
import { Skeleton } from "@/components/ui/skeleton";
import BroadcastBanner from "@/components/BroadcastBanner";
import DashboardStatusBanners from "@/components/dashboard/DashboardStatusBanners";
import PayItForwardTeaser from "@/components/dashboard/PayItForwardTeaser";
import { DashboardBannedScreen, DashboardDeniedScreen } from "@/components/dashboard/DashboardBlockedScreen";

// Dialogs and overlays — none are visible on first paint. Each is code-split
// and only the dialogs the user actually opens get fetched, keeping the
// Dashboard route chunk small.
const JobDetailDialog = lazy(() => import("@/components/dashboard/JobDetailDialog"));
const ApplyBody = lazy(() => import("@/components/dashboard/applyConfirmDialog/ApplyBody").then(m => ({ default: m.ApplyBody })));
const ApplyConfirmDialog = lazy(() => import("@/components/dashboard/ApplyConfirmDialog").then(m => ({ default: m.ApplyConfirmDialog })));
const ReportDialog = lazy(() => import("@/components/ReportDialog"));
const OnboardingTour = lazy(() => import("@/components/OnboardingTour"));
const BirthdayPopup = lazy(() => import("@/components/BirthdayPopup"));
// Map column for the web-desktop two-pane (the map surface pulls Apple's
// MapKit JS from the CDN — lazy so the phone/native feed never pays for it).
const BrowseMap = lazy(() => import("@/components/BrowseMap").then(m => ({ default: m.BrowseMap })));
import SectionBoundary from "@/components/SectionBoundary";
import { useDashboardData } from "@/hooks/useDashboardData";
import { usePendingSaveConsumer } from "@/hooks/usePendingSaveConsumer";
import { usePrefetchUserData } from "@/hooks/usePrefetchUserData";
import { useDashboardFilters } from "@/hooks/useDashboardFilters";
import { safeStorage } from "@/lib/safeStorage";
import { usePersistedBrowseView } from "@/hooks/usePersistedBrowseView";
import { useJobRef } from "@/hooks/useJobRef";
import type { HelperAvailabilitySlot } from "./dashboard/dashboardTypes";
import { QuickApplyHandler } from "./dashboard/QuickApplyHandler";
import { useDashboardSideQueries } from "./dashboard/useDashboardSideQueries";
import { useSaveJob } from "./dashboard/useSaveJob";
import { useApplyFlow } from "./dashboard/useApplyFlow";
import { useDetailJob } from "./dashboard/useDetailJob";


const Dashboard = () => {
  const navigate = useNavigate();
  // Matches the h1 this page renders ("Browse Jobs" — LoadingHeading and
  // BrowseTasksToolbar both), not the route name. "Dashboard — Helpr" named a
  // word that appears nowhere on the screen.
  usePageTitle("Browse Jobs — Helpr");

  // The Filters button lives in the title card (BrowseTasksActions) while the
  // filter panel lives in BrowseTasksToolbar below it. This page is the one
  // component that renders both, so it owns the ref that joins them — on the
  // desktop web the panel opens as a popover anchored to that button instead
  // of a modal sheet over the results. Phone + native are unaffected.
  const filtersButtonRef = useRef<HTMLButtonElement>(null);
  const [searchParams, setSearchParams] = useSearchParams();
  // Capture ?ref= attribution from deep-links (push notifications, share
  // links, etc.) so analytics can attribute which surface drove the open.
  useJobRef();

  const {
    user, profile, isAdmin, loading, helprTier, allJobs, platformFee,
    helperAvailability, recommendedJobs, refresh, loadError,
    fetchNextPage, hasNextPage, isFetchingNextPage,
  } = useDashboardData();

  // Sentinel for infinite scroll — fires fetchNextPage when ~80% of the list is in view.
  const loadMoreRef = useRef<HTMLDivElement | null>(null);
  useEffect(() => {
    const node = loadMoreRef.current;
    if (!node || !hasNextPage || isFetchingNextPage) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) fetchNextPage();
      },
      // rootMargin pulls the trigger ~20% of viewport early (~80% scroll point)
      { root: null, rootMargin: "0px 0px 20% 0px", threshold: 0 },
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [hasNextPage, isFetchingNextPage, fetchNextPage, allJobs.length]);

  const { containerRef, pullDistance, refreshing, isPulling } = usePullToRefresh({
    onRefresh: refresh,
  });

  useRealtimePush(user?.id ?? null);
  // Guest bookmark -> signup -> this saves the job they wanted kept.
  usePendingSaveConsumer(user?.id);
  // Warm Referral / Activity / Jobs caches in the background — makes the next tap feel instant.
  usePrefetchUserData(user?.id);

  const filters = useDashboardFilters({
    allJobs, userId: user?.id, profile, helprTier, helperAvailability: helperAvailability as HelperAvailabilitySlot[],
    // Same rate the feed cards render with (`effectiveFee` below is this
    // value) — the pay sorts have to order by the number on the card.
    effectiveFee: platformFee,
  });

  // The greeting card's "stat of the day" line was removed — it added a
  // third line to the title card and pushed the job feed down. The
  // headline job count it surfaced still shows in the date eyebrow.

  // Stripe sends a paid boost back to `/dashboard?boosted=<jobId>` (and a
  // bailed one to `?boost_cancelled=<jobId>`). Nothing consumed either param,
  // so a poster who had just paid for a boost landed on the feed with no
  // confirmation at all — the Boosted badge only appears later, on My Posts.
  // The toast carries an action so it survives the suppress-plain-success
  // policy (see lib/toastPolicy.ts): the toast IS the route to the boosted post.
  useEffect(() => {
    const boosted = searchParams.get("boosted");
    const boostCancelled = searchParams.get("boost_cancelled");
    if (!boosted && !boostCancelled) return;
    if (boosted) {
      // `?boosted` IS the job id, so send the tap to that job rather than to
      // My Posts' default "Needs you" bucket — a freshly-boosted open post
      // with nobody on it yet buckets to `waiting`, so a bare /my-posts landed
      // on an empty list.
      toast.success("Your job is boosted — it's at the top of the feed for the next 24 hours.", {
        action: { label: "View", onClick: () => navigate(`/my-posts?job=${boosted}`) },
      });
    } else {
      toast.error("Boost cancelled — your job is still posted, just not boosted.");
    }
    const next = new URLSearchParams(searchParams);
    next.delete("boosted");
    next.delete("boost_cancelled");
    setSearchParams(next, { replace: true });
  }, [searchParams, setSearchParams, navigate]);

  const [reportJobId, setReportJobId] = useState<string | null>(null);
  /**
   * ONE overlay at a time on first login.
   *
   * The onboarding tour and the birthday greeting are both Radix modals at
   * `z-50` mounted as unconditional siblings below. They opened independently,
   * so a member whose first login fell on their birthday got both at once —
   * the tour card (337×191) painted straight over the greeting (187×250),
   * which was on screen but completely covered and unreachable until the tour
   * was skipped. Neither knew the other existed; nothing was stacking them
   * wrong, they were simply racing.
   *
   * The tour reports whether it still owns the screen and the greeting waits
   * on that, so the order is now fixed: tour, then birthday. Starts `true`
   * (defer) because the tour's own answer is asynchronous — see
   * `onActiveChange` on OnboardingTour.
   */
  const [tourActive, setTourActive] = useState(true);
  // Detail-dialog open/close lifecycle (which job, feed-scroll restore, and
  // ?job=<id> URL mirroring) lives in useDetailJob.
  const { detailJob, openDetailJob, closeDetailJob } = useDetailJob({
    containerRef, searchParams, setSearchParams, allJobs,
  });
  const [expandedCardId, setExpandedCardId] = useState<string | null>(null);
  // List vs Map view. The map shows the same open jobs as the list,
  // pinned to neighborhood-rounded coords (privacy via the
  // get_open_jobs_for_map RPC). Toggle persists for the session only —
  // resetting to "list" on next mount matches user expectation that
  // the default landing surface is the curated feed.
  const [view, setView] = usePersistedBrowseView("list");

  // Web desktop (≥1024px, non-native) composes the feed and the map
  // side by side, so the list/map toggle is meaningless there and the
  // feed is locked to "list" — the map always occupies its own column.
  const isWebDesktop = useIsWebDesktop();

  // Feed density — comfortable (full cards) or compact (48px rows). Read from
  // any persisted preference; the in-toolbar toggle was removed for a cleaner
  // Browse Tasks header, so this is now read-only (defaults to comfortable).
  const [density] = useState<FeedDensity>(() => {
    try {
      const stored = window.localStorage.getItem("job-feed-density");
      return stored === "compact" || stored === "comfortable" ? stored : "comfortable";
    } catch { return "comfortable"; }
  });

  /**
   * Show only saved jobs.
   *
   * Saving a job had no destination at all — the bookmark on every card wrote
   * to a list nobody could open (owner: "how can they see saved jobs?"). This
   * is deliberately a FILTER on the feed rather than a new screen: a saved job
   * is still a job you might apply to, and it should sit in the surface that
   * knows how to apply to it, with the same cards and the same actions.
   *
   * Not persisted — unlike the map pane, this is a lens you look through and
   * step back out of, not a layout preference.
   */
  const [savedOnly, setSavedOnly] = useState(false);
  const toggleSavedOnly = useCallback(() => setSavedOnly((v) => !v), []);

  /**
   * Is the map column showing? Desktop website only.
   *
   * The map is a second way to read the same board, not a required half of the
   * screen — a helpr who knows their parish wants the list at full width
   * (owner: "give them the option to get rid of the map"). Persisted, because a
   * pane that reappears on every route change is one the user has to dismiss
   * repeatedly. Default ON: the split view is the desktop layout, and a map
   * nobody has been told exists is worse than one they can close.
   */
  const [mapVisible, setMapVisible] = useState<boolean>(
    () => safeStorage.getItem("helpr.browseMapVisible") !== "0",
  );
  // The storage write is OUTSIDE the updater on purpose. React's StrictMode
  // invokes a state updater twice in development to surface exactly this: with
  // the setItem inside, the first call stored "0" and the second — re-run
  // against the already-flipped value — stored "1" again, so the button
  // appeared to do nothing at all.
  const toggleMap = useCallback(() => {
    const next = !mapVisible;
    setMapVisible(next);
    safeStorage.setItem("helpr.browseMapVisible", next ? "1" : "0");
  }, [mapVisible]);

  // Desktop split-screen hover sync — hovering a list card scales up the
  // corresponding map pin. null = no card hovered.
  const [hoveredJobId, setHoveredJobId] = useState<string | null>(null);

  // Gift cards — count of funded, unspent gift cards addressed to THIS user.
  // Shown as a teaser banner above the community teaser when > 0. The email
  // is needed as well as the id: a gift is named to an address and only gains
  // a `recipient_id` once claimed, so an unclaimed one is invisible by id.
  // (This was keyed off the user's parish, which matched nothing — see the
  // query's comment in useDashboardSideQueries.)
  const {
    pifCount,
    savedJobIds, setSavedJobIds, dismissedJobIds, setDismissedJobIds,
  } = useDashboardSideQueries({ userId: user?.id, userEmail: user?.email, allJobs });

  // Profile-completion is no longer nudged on the home feed — the full
  // "Finish your profile" card pushed the job feed below the fold. The
  // completion checklist / progress meter lives on the Profile landing
  // screen instead (ProfileLanding's completion meter), which is the
  // surface the user navigates to in order to act on it.

  const effectiveFee = platformFee;

  const { handleToggleSave } = useSaveJob({ user, savedJobIds, setSavedJobIds });

  const {
    confirmApplyJobId, setConfirmApplyJobId, confirmApplyJob,
    applyMessage, setApplyMessage, applyLoading, applyFiles, setApplyFiles,
    handleApplyRequest, handleApplyConfirm,
  } = useApplyFlow({ user, allJobs });

  // Immediate optimistic dismiss + toast/Undo (owner: the "Not Interested?"
  // confirm dialog was a whole modal for a reversible, purely-local action —
  // same mismatch as the attachment-remove undo in AppliedJobsTab). The job
  // drops off the feed right away; Undo puts the id back in storage + state.
  const handleDismissRequest = useCallback((jobId: string) => {
    setDismissedJobIds(prev => {
      const next = new Set(prev);
      next.add(jobId);
      safeStorage.setItem("helpr_dismissed_jobs", JSON.stringify([...next]));
      return next;
    });
    toast.success("Job removed from your feed", {
      action: {
        label: "Undo",
        onClick: () => {
          setDismissedJobIds(prev => {
            const next = new Set(prev);
            next.delete(jobId);
            safeStorage.setItem("helpr_dismissed_jobs", JSON.stringify([...next]));
            return next;
          });
        },
      },
    });
  }, [setDismissedJobIds]);

  // The in-progress pill is no longer rendered in the brand row (owner:
  // "remove"). That row is logo, filter, notification. The job it pointed at is
  // still one tap away via the Jobs tab, and DashboardInProgressBadge itself
  // stays — ScheduleTab imports `inProgressBadgeTarget` from it.


  if (loading) {
    // Loading state mirrors the *exact* loaded layout: the same
    // PageScaffold two-card shell (brand title card over a raised panel)
    // with a skeleton body, not a bare AppShell + stack of cards.
    // Sharing the scaffold means the title card and panel keep their
    // size and position, so when the data resolves the feed settles in
    // place instead of popping in and shoving everything down. The title
    // bar is the REAL one rather than a skeleton: nothing in it depends on
    // the pending feed query, so rendering a placeholder would only make it
    // flicker into itself.
    return (
      <PageScaffold
        animate
        panelElevation="raised"
        // Full-bleed app bar — web-desktop ONLY. Passing it unconditionally
        // would add a second, in-flow sticky header on phone/native (where
        // the "Full-bleed top header" CSS rule never fires), stacking on top
        // of the title card's own emblem+bell instead of replacing them.
        titleCard={<DashboardTitleBar
            actions={<BrowseTasksActions filters={filters} filtersButtonRef={filtersButtonRef} />}
            searchBar={filters.searchOpen ? <BrowseSearchBar filters={filters} /> : undefined}
          />}
        titleCardClassName={TITLE_BAR_PADDING}
      >
        {/* The loaded screen's only <h1> lives in BrowseTasksToolbar, which
            doesn't exist yet here — so the pending screen had no heading at
            all. Visually hidden; the skeleton stays the visible design. */}
        <LoadingHeading title="Browse Jobs" message="Loading jobs near you…" />
        <DashboardSkeleton />
      </PageScaffold>
    );
  }

  // Prefer the profile's stored full name, then auth metadata, then the email
  // local-part — never fall back to the literal word "User" in greetings.
  const rawName =
    (profile?.full_name && profile.full_name.trim()) ||
    (user?.user_metadata?.full_name && String(user.user_metadata.full_name).trim()) ||
    (user?.user_metadata?.name && String(user.user_metadata.name).trim()) ||
    "";
  const emailLocal = user?.email ? user.email.split("@")[0] : "";
  const firstName = (rawName || emailLocal || "there").split(" ")[0];
  const approvalStatus = profile?.approval_status;
  const banStatus = profile?.ban_status || "active";

  // Block banned users
  if (!isAdmin && (banStatus === "permanently_banned" || banStatus === "temp_banned")) {
    return <DashboardBannedScreen banStatus={banStatus} />;
  }

  // Progressive activation: a `pending` user is NOT walled out of the
  // dashboard. They can browse, save and apply while review runs — the
  // verification gate fires only at the moments that genuinely need it
  // (IDV-before-accept in Activity.tsx, payout setup). A non-blocking
  // "under review" banner is rendered in `beforePanel` below instead.
  //
  // `denied` is still a hard stop here as defense-in-depth — ProtectedRoute
  // already redirects denied users to /account-denied before this renders,
  // but if that ever fails to fire we must not leak the feed to them.
  if (!isAdmin && profile && approvalStatus === "denied") {
    const handleSignOut = async () => {
      await signOutWithPushCleanup();
      navigate("/login", { replace: true });
    };
    return <DashboardDeniedScreen onSignOut={handleSignOut} />;
  }

  const isPendingReview = !isAdmin && !!profile && approvalStatus === "pending";



  return (
    <>
    <PageScaffold
      animate
      panelElevation="raised"
      // A slim toolbar above the feed (owner: "move to section above the job
      // card"). On desktop it carries only the search + filter controls — the
      // emblem and bell live in the global app bar, and the IN PROGRESS pill
      // was removed outright (owner). Phone/native keep the full card,
      // emblem + pill included, since they have no app bar to hold them.
      // MERGED (owner: "merge"). On the desktop website there is no separate
      // floating title card above the panel any more — it was a second box
      // stating nothing the app bar doesn't already carry, and it spanned the
      // map as well as the feed. Its one remaining job, the search + filter
      // controls, moved INTO the panel directly above the job cards (see the
      // feed column below), so the screen is one box.
      //
      // Phone and native keep the card exactly as it was: they have no app
      // bar, so this is the only thing carrying the emblem and the live
      // in-progress pill.
      titleCard={
        isWebDesktop ? undefined : (
          <DashboardTitleBar
            actions={
              <BrowseTasksActions
                filters={filters}
                filtersButtonRef={filtersButtonRef}
                savedOnly={savedOnly}
                onToggleSavedOnly={toggleSavedOnly}
                savedCount={savedJobIds.size}
                // Phone + native: emblem, search, filter, bell. Search is no
                // longer folded into the sheet — the row this cluster has to
                // fit is nothing like the five-control row that argument was
                // measured against, and the fold left 158px of dead band in
                // the middle of the brand row with search unreachable except
                // through the Filters drawer. See BrowseTasksActions.
              />
            }
            searchBar={filters.searchOpen ? <BrowseSearchBar filters={filters} /> : undefined}
          />
        )
      }
      titleCardClassName={TITLE_BAR_PADDING}
      aboveTitle={<BroadcastBanner />}
      beforePanel={
        <>
          <DashboardStatusBanners
            isPendingReview={isPendingReview}
            onPendingClick={() => navigate("/account-pending")}
          />

          {/* The "Your Helprs" quick-rebook strip used to render here,
              wrapped in a SectionBoundary. Removed 2026-08-19 at the owner's
              request — it pushed the job feed down on the home tab for a
              shortcut that only pays off for repeat customers. Rebooking a
              saved helper still lives on Profile -> Saved Helprs, which is
              where the full list is. The component was kept unrendered for a
              while in case it returned; it was deleted on 2026-08-25 in the
              dead-code sweep and is recoverable from git history. */}
          {/* The "Finish your profile" completion nudge used to render
              here. It moved off the home feed onto the Profile landing
              screen (ProfileLanding's completion meter) so the job feed
              is no longer pushed below the fold. */}

          {/* The soft push opt-in — the READER half of
              useNotificationPermissionPrompt, which had a writer but no
              consumer, so it had never appeared to anyone. Self-suppressing:
              renders null until the user has posted or applied, and null once
              permission is decided or the prompt is snoozed. So the cold home
              screen still shows nothing here, which is what the 2026-05-29
              redesign asked for when it pulled the cold-launch version. Slim
              one-line pill by design — it must not push the feed below the
              fold. `:has(>*)` keeps the padding off when it renders null.

              `empty:hidden` is load-bearing, not decoration. This div is a
              `beforePanel` sibling inside PageScaffold's `flex flex-col
              gap-3 lg:gap-4` column — so even fully empty (0×0, no padding)
              it still cost one extra flex GAP between the title card and the
              panel below, on top of the gap the column already puts between
              every pair of siblings. Measured: Home's title-card-bottom to
              first-card-top ran 38px against My Posts' 25px for the
              identical PageScaffold gap — the entire 13px difference was
              this one empty flex item's phantom gap, not a real padding
              value anywhere. `PushNotificationPrompt` returns null (no DOM
              node at all) on the cold path most sessions hit, which is
              exactly when `:empty` matches and `display:none` pulls this
              item out of the flex flow, closing the gap on both sides of it
              — so Home lands on the SAME 25px rhythm every other screen
              already uses instead of drifting by whatever this slot happens
              to render. */}
          <div className="px-4 [&:has(>*)]:pb-2 empty:hidden">
            <PushNotificationPrompt />
          </div>

          {/* Promo/nudge banner slot intentionally empty — the home screen
              shows the greeting, the saved-helpers row, "For you", and the
              job feed with no marketing/upsell cards in between. */}
        </>
      }
    >
            {/* The standalone "For you" carousel was removed: it duplicated
                the job feed (same jobs as Browse at low inventory) and ate a
                whole horizontal band. Personalization now lives in the single
                Browse feed as ORDER — the "Picked for you" group surfaces
                relevance-ranked jobs at the top, then "Everything else". One
                clean, personalized, vertical list; no duplication. */}

            {/* Browse-tasks feed is the main scroll surface of the
                dashboard. Wrap so a render error in any job card (rare,
                but cheap insurance) shows an inline retry banner inside
                the panel rather than blanking the entire route. The
                page-level ErrorBoundary above still catches anything
                that escapes this. */}
            <SectionBoundary label="the job feed">
              {/* The job feed fills the frame. The map is reached via the
                  toolbar list/map toggle (BrowseMap inside BrowseTasksFeed),
                  not a side panel — a fixed split-screen map clipped at the
                  edge of the centered phone-width frame. */}
              <div className="flex flex-1 min-h-0 overflow-hidden">
                <div className="flex-1 min-w-0 overflow-hidden flex flex-col">
                  {/* The feed's own controls, above the CARDS and nothing else
                      (owner: "add section above just the job cards like it's
                      their own box"). On the desktop website this column is one
                      of two — a full-width strip above both would be filtering
                      the map as much as the list, which is not what the search
                      field does. Phone/native have no second column, so this
                      renders exactly where the strip used to. */}
                  {isWebDesktop && (
                    <div
                      className="shrink-0 flex items-center gap-2 px-4 py-2"
                      style={{ borderBottom: "1px solid hsl(var(--olivewood) / 0.12)" }}
                    >
                      {filters.searchOpen ? (
                        <BrowseSearchBar filters={filters} />
                      ) : (
                        <>
                          {/* THE ROW EARNS ITS HEIGHT. With the emblem hidden
                              on web-desktop and no title on this screen (owner:
                              "home will not have a title just the H logo"), the
                              left half of this 44px band was empty and the four
                              icons huddled at the right — a full row saying
                              nothing above the list it belongs to.
                              The count is what it can honestly say instead:
                              live, about the list directly beneath, and the
                              same shape as the "N unread" and bucket counts
                              every sibling screen puts in that slot. */}
                          <span
                            /* Bumped from ds-13 to ds-16 to match the desktop
                               sidebar nav's own link size (owner, 2026-08-31:
                               "17 jobs should be the same size fonta as the
                               info on the right panel"). Still font-display
                               italic, same family as the status-tab count this
                               previously matched. */
                            className="font-display italic text-ds-16 leading-none min-w-0 truncate"
                            /* --ink-deep, matching the SELECTED status tab on
                               Posts and Jobs — those went black in the same
                               pass and this is the same label in the same slot
                               (owner: "black and same size as other pages"). */
                            style={{ color: "hsl(var(--ink-deep))" }}
                          >
                            {/* True total under the current filters
                                (useDashboardJobsCount), not
                                `filteredJobs.length` — the feed is
                                paginated via infinite scroll, so that only
                                counts jobs loaded into memory so far and
                                undercounted against the map's honest total
                                (owner: "13 jobs" on the list vs "14 Jobs"
                                on the map). Fall back to the loaded count
                                while the true-total query is in flight so
                                the header never shows nothing. */}
                            {filters.totalMatchingCount ?? filters.filteredJobs.length}
                            {(filters.totalMatchingCount ?? filters.filteredJobs.length) === 1 ? " job" : " jobs"}
                            {filters.hasFilters ? " match your filters" : ""}
                          </span>
                        <div className="flex items-center gap-1 ml-auto">
                          <BrowseTasksActions
                            filters={filters}
                            filtersButtonRef={filtersButtonRef}
                            savedOnly={savedOnly}
                            onToggleSavedOnly={toggleSavedOnly}
                            savedCount={savedJobIds.size}
                          />
                          {/* Show / hide the map column. It sits with search
                              and filters because it is the same kind of
                              control — it changes how you read the board, not
                              what is on it. */}
                          <button
                            type="button"
                            onClick={toggleMap}
                            aria-pressed={mapVisible}
                            aria-label={mapVisible ? "Hide the map" : "Show the map"}
                            title={mapVisible ? "Hide the map" : "Show the map"}
                            className={`h-10 w-10 rounded-ds-md inline-flex items-center justify-center btn-press transition-colors ${
                              mapVisible
                                ? "text-[hsl(var(--bark))] bg-[hsl(var(--bark)/0.10)]"
                                : "text-muted-foreground hover:text-foreground hover:bg-[hsl(var(--bark)/0.06)]"
                            }`}
                          >
                            {mapVisible ? (
                              <Map className="w-5 h-5" />
                            ) : (
                              <MapPinned className="w-5 h-5" />
                            )}
                          </button>
                        </div>
                        </>
                      )}
                    </div>
                  )}

                  <BrowseTasksToolbar
                    filtersAnchorRef={filtersButtonRef}
                    titleSrOnly
                    filters={filters}
                    user={user}
                    helperAvailability={helperAvailability}
                    view={view}
                    setView={setView}
                    hideViewToggle={isWebDesktop}
                    // NO `compactActions`. That flag grew a second Search
                    // field inside the filter sheet for exactly the surfaces
                    // whose header row had lost the search icon — and the
                    // header row has it back on every width now, so passing it
                    // would put two search fields on one screen. "Only saved
                    // jobs" is unaffected: it comes from
                    // buildJobFilterSections, not from this flag.
                    savedOnly={savedOnly}
                    onToggleSavedOnly={toggleSavedOnly}
                    savedCount={savedJobIds.size}
                    onClearAllFilters={() => {
                      // After clearing filters, snap the feed back to the top
                      // so the user lands on the fresh unfiltered head of the
                      // list rather than mid-scroll where the old filter ended.
                      const el = containerRef.current;
                      if (el) el.scrollTo({ top: 0, behavior: "smooth" });
                    }}
                  />

                  <BrowseTasksFeed
                    view={isWebDesktop ? "list" : view}
                    density={density}
                    filters={filters}
                    user={user}
                    allJobs={allJobs}
                    loadError={loadError}
                    refresh={refresh}
                    recommendedJobs={recommendedJobs}
                    // Reserve the "Picked for you" slot with skeletons only while a
                    // pull-to-refresh re-derives recommendations and no picks exist
                    // yet, so the empty→filled swap doesn't shove the list down (CLS).
                    // NOT keyed on isFetchingNextPage: the recommended section belongs
                    // to the first page only, so infinite-scroll pagination would
                    // otherwise flash two placeholder cards at the top of the feed
                    // every time the next page loads with zero recommendations.
                    recommendedLoading={refreshing}
                    dismissedJobIds={dismissedJobIds}
                    savedOnly={savedOnly}
                    effectiveFee={effectiveFee}
                    handleApplyRequest={handleApplyRequest}
                    handleDismissRequest={handleDismissRequest}
                    handleToggleSave={handleToggleSave}
                    expandedCardId={expandedCardId}
                    setExpandedCardId={setExpandedCardId}
                    savedJobIds={savedJobIds}
                    setReportJobId={setReportJobId}
                    setDetailJob={openDetailJob}
                    containerRef={containerRef}
                    pullDistance={pullDistance}
                    refreshing={refreshing}
                    isPulling={isPulling}
                    loadMoreRef={loadMoreRef}
                    hasNextPage={hasNextPage}
                    isFetchingNextPage={isFetchingNextPage}
                    fetchNextPage={fetchNextPage}
                    hoveredJobId={hoveredJobId}
                    setHoveredJobId={setHoveredJobId}
                  />
                </div>
                {/* Web-desktop only: the map rides alongside the feed in its
                    own column rather than hiding behind a toggle. The page
                    frame is full-width here (PageScaffold desktop), so the
                    map has real room and doesn't clip at a phone-width edge
                    the way the old side-map did (#12). */}
                {isWebDesktop && mapVisible && (
                  <div
                    className="w-[48%] shrink-0 min-h-0 flex flex-col"
                    style={{ borderLeft: "1px solid hsl(var(--olivewood) / 0.12)" }}
                  >
                    <Suspense fallback={<Skeleton className="h-full w-full rounded-2xl" />}>
                      <BrowseMap
                        flush
                        // Same job-detail dialog the feed's cards open on
                        // tap (openDetailJob), not the quick-apply sheet —
                        // see the matching note in BrowseTasksFeed.tsx.
                        onJobAction={(jobId) => {
                          const job = allJobs.find((j) => j.id === jobId);
                          if (job) openDetailJob(job);
                        }}
                        currentUserId={user?.id}
                        filters={filters.mapFilter}
                        onClearFilters={filters.clearFilters}
                        // MUST match the feed column beside it. Without this
                        // prop BrowseMap falls back to guest pricing and the
                        // pin preview prints the GROSS budget, so on this exact
                        // screen "Pressure wash a house exterior" read $368 in
                        // the list and $400 on the map, side by side, for the
                        // same job (caught 2026-08-31 at 1440). Same value the
                        // list's JobCards use — one number per job, everywhere.
                        effectiveFee={effectiveFee}
                      />
                    </Suspense>
                  </div>
                )}
              </div>
            </SectionBoundary>

            {/* Pay It Forward teaser — only shown when credits exist in the user's parish */}
            <PayItForwardTeaser pifCount={pifCount} />

    </PageScaffold>

      {/* Dialog chunks load on demand — only mounted once the user opens
          them, so the Dashboard route chunk doesn't carry them. */}
      {detailJob && (
        <Suspense fallback={null}>
          <JobDetailDialog
            job={detailJob}
            effectiveFee={effectiveFee}
            allJobs={allJobs}
            isSaved={detailJob ? savedJobIds.has(detailJob.id) : false}
            onToggleSave={handleToggleSave}
            userLat={filters.userLoc?.status === "ready" ? filters.userLoc.lat : null}
            userLng={filters.userLoc?.status === "ready" ? filters.userLoc.lng : null}
            /* Dismissing the sheet abandons the apply too. Without clearing
               the pending id, closing from the apply step left
               confirmApplyJobId set with no detail sheet to host it — and the
               standalone deep-link sheet below (which renders whenever that id
               is set and does NOT match an open detail job) would immediately
               pop the apply form back up on the bare feed. */
            onClose={() => { setConfirmApplyJobId(null); closeDetailJob(); }}
            onApply={handleApplyRequest}
            onReport={setReportJobId}
            onSelect={openDetailJob}
            /* THE APPLY STEP, RENDERED IN THE SAME SHEET.
               Applying used to close this sheet and open a separate centred
               AlertDialog, so one continuous act played as three motions
               across two anchors (owner, 2026-08-28). ApplyBody now renders as
               the second step of this surface; useApplyFlow still owns all the
               state and the mutation, so nothing about submitting changed —
               only where the markup mounts. */
            applyStep={({ onBack }) =>
              confirmApplyJob ? (
                <Suspense fallback={null}>
                  <ApplyBody
                        open
                        onClose={() => setConfirmApplyJobId(null)}
                        confirmApplyJob={confirmApplyJob}
                        platformFee={platformFee}
                        applyMessage={applyMessage}
                        setApplyMessage={setApplyMessage}
                        applyFiles={applyFiles}
                        setApplyFiles={setApplyFiles}
                        applyLoading={applyLoading}
                        hideEarnings
                        onBack={onBack}
                        handleApplyConfirm={() => {
                          // Submitting takes the whole sheet down — the helpr
                          // is done with this job either way, and the success
                          // toast is the confirmation.
                          handleApplyConfirm();
                          closeDetailJob();
                        }}
                  />
                </Suspense>
              ) : null
            }
          />
        </Suspense>
      )}

      {reportJobId && (
        <Suspense fallback={null}>
          <ReportDialog open={!!reportJobId} onClose={() => setReportJobId(null)} reportedType="job" reportedId={reportJobId} />
        </Suspense>
      )}

      {/* Birthday greeting — a popup, not chrome. It used to be mounted as a
          sibling of the (now removed) app bar inside PageScaffold's `header`
          slot; it lives with the other overlays now. Still mounted on every
          Dashboard render — it self-hides unless today is the user's birthday. */}
      <Suspense fallback={null}>
        <BirthdayPopup
          dateOfBirth={profile?.date_of_birth}
          firstName={firstName}
          deferred={tourActive}
        />
      </Suspense>

      <Suspense fallback={null}>
        <OnboardingTour
          profileComplete={isProfileComplete(profile)}
          userId={user?.id}
          onActiveChange={setTourActive}
        />
      </Suspense>
      <QuickApplyHandler searchParams={searchParams} user={user} allJobs={allJobs} onApply={handleApplyRequest} />


      {/* STANDALONE apply sheet — only for the QuickApply deep link
          (`?apply=<jobId>`), where no detail sheet is open to host the step.
          When the detail sheet IS open it renders the apply step itself, and
          mounting this too would stack a second surface over it. */}
      {confirmApplyJobId && confirmApplyJobId !== detailJob?.id && (
        <Suspense fallback={null}>
          <ApplyConfirmDialog
            open={!!confirmApplyJobId}
            onClose={() => setConfirmApplyJobId(null)}
            confirmApplyJob={confirmApplyJob}
            platformFee={platformFee}
            applyMessage={applyMessage}
            setApplyMessage={setApplyMessage}
            applyFiles={applyFiles}
            setApplyFiles={setApplyFiles}
            applyLoading={applyLoading}
            handleApplyConfirm={handleApplyConfirm}
          />
        </Suspense>
      )}

      {/* No payout-setup dialog here. It was mounted behind a
          `payoutSetupDialogOpen` flag whose setter was never called from
          anywhere, so it could not open — a lazy chunk and a piece of state
          maintained for a dialog no user could ever see.

          Nor should it open here: applying to a job does not require a payout
          account, accepting one does, and that gate already exists in
          useOfferHandlers (with a "Set up payouts" action on the toast). Adding
          a second gate at apply time would put the friction at the wrong
          moment. This was PayoutSetupDialog's only mount point, so the
          component had no reachable caller at all and is deleted with it. */}

      {/* Floating-FAB removed — MobileNav already renders a Post FAB at the
          right edge of the bottom dock. Two FABs at the same screen corner
          was the "stacked plus buttons" bug visible in TestFlight build
          screenshots. Desktop surfaces the CTA in the header (md:flex)
          so no desktop replacement is needed. */}

    </>
  );
};

export default Dashboard;
